/// Written into byte 0 of an occupied slot. An arbitrary non-zero value: a
/// blank EEPROM cell reads 0xFF and an erased one reads 0x00, so neither of the
/// two states a fresh or wiped device is in can look occupied.
constexpr uint8_t kOccupied = 0xC5U;

constexpr uint16_t kKeyField = hal::kStoreMaxKeyLen + 1U; // 16, NUL included
constexpr uint16_t kSlotSize = 1U + kKeyField + 1U + hal::kStoreMaxValueLen;

uint16_t slotBase(uint8_t slot) {
  return static_cast<uint16_t>(kEepromBase + static_cast<uint16_t>(slot) * kSlotSize);
}

bool validKey(const char* key) {
  if (key == nullptr || key[0] == '\0') {
    return false;
  }
  for (uint8_t i = 0U; i <= hal::kStoreMaxKeyLen; ++i) {
    if (key[i] == '\0') {
      return true;
    }
  }
  return false;
}

bool slotHoldsKey(uint8_t slot, const char* key) {
  const uint16_t base = slotBase(slot);
  if (EEPROM.read(base) != kOccupied) {
    return false;
  }
  for (uint8_t i = 0U; i < kKeyField; ++i) {
    const uint8_t stored = EEPROM.read(static_cast<int>(base + 1U + i));
    const uint8_t wanted = static_cast<uint8_t>(key[i]);
    if (stored != wanted) {
      return false;
    }
    if (wanted == 0U) {
      return true;
    }
  }
  return true;
}

/// kEepromSlots when there is no slot holding `key`.
uint8_t findKey(const char* key) {
  for (uint8_t i = 0U; i < kEepromSlots; ++i) {
    if (slotHoldsKey(i, key)) {
      return i;
    }
  }
  return kEepromSlots;
}

/// kEepromSlots when every slot is occupied.
uint8_t findFree() {
  for (uint8_t i = 0U; i < kEepromSlots; ++i) {
    if (EEPROM.read(static_cast<int>(slotBase(i))) != kOccupied) {
      return i;
    }
  }
  return kEepromSlots;
}

void writeRecord(uint8_t slot, const char* key, const uint8_t* value, uint8_t len) {
  const uint16_t base = slotBase(slot);
  // Marker first: see the header. A slot that is visibly occupied with contents
  // the caller's integrity check rejects is recoverable; one that looks like a
  // finished record but was never filled in is not.
  EEPROM.update(static_cast<int>(base), kOccupied);
  // Stops at the terminator. Bytes past it in the slot keep whatever the
  // previous, longer key left there; slotHoldsKey() compares only up to the
  // NUL, so they are unreachable rather than merely tidy.
  for (uint8_t i = 0U; i < kKeyField; ++i) {
    const uint8_t c = static_cast<uint8_t>(key[i]);
    EEPROM.update(static_cast<int>(base + 1U + i), c);
    if (c == 0U) {
      break;
    }
  }
  EEPROM.update(static_cast<int>(base + 1U + kKeyField), len);
  for (uint8_t i = 0U; i < len; ++i) {
    EEPROM.update(static_cast<int>(base + 2U + kKeyField + i), value[i]);
  }
}

