hal::StoreResult EepromStore::put(const char* key, const uint8_t* value, uint8_t len) {
  if (!validKey(key) || value == nullptr || len > hal::kStoreMaxValueLen) {
    return hal::StoreResult::kTooLarge;
  }
  uint8_t slot = findKey(key);
  if (slot >= kEepromSlots) {
    slot = findFree();
  }
  if (slot >= kEepromSlots) {
    return hal::StoreResult::kNoSpace;
  }
  writeRecord(slot, key, value, len);
  return hal::StoreResult::kOk;
}

hal::StoreResult EepromStore::get(const char* key, uint8_t* out, uint8_t cap, uint8_t& outLen) {
  outLen = 0U;
  if (!validKey(key) || out == nullptr) {
    return hal::StoreResult::kTooLarge;
  }
  const uint8_t slot = findKey(key);
  if (slot >= kEepromSlots) {
    return hal::StoreResult::kNotFound;
  }
  const uint16_t base = slotBase(slot);
  const uint8_t len = EEPROM.read(static_cast<int>(base + 1U + kKeyField));
  if (len > hal::kStoreMaxValueLen) {
    // Structurally impossible, so the record is not a record. Honouring the
    // length would read past the slot and hand back somebody else's key.
    return hal::StoreResult::kNotFound;
  }
  if (len > cap) {
    return hal::StoreResult::kTooLarge;
  }
  for (uint8_t i = 0U; i < len; ++i) {
    out[i] = EEPROM.read(static_cast<int>(base + 2U + kKeyField + i));
  }
  outLen = len;
  return hal::StoreResult::kOk;
}

hal::StoreResult EepromStore::erase(const char* key) {
  if (!validKey(key)) {
    return hal::StoreResult::kTooLarge;
  }
  const uint8_t slot = findKey(key);
  if (slot >= kEepromSlots) {
    // Reported, not treated as success: erasing an absent key is how a typo in
    // the factory-reset path shows itself.
    return hal::StoreResult::kNotFound;
  }
  EEPROM.update(static_cast<int>(slotBase(slot)), 0U);
  return hal::StoreResult::kOk;
}

